<section class="page"><a class="text-button" href="<?=url()?>">← E’lonlarga qaytish</a><div class="detail-grid"><article class="panel"><div class="eyebrow small"><?=e($item['category_name'])?> · <?=e($item['city'])?></div><h1><?=e($item['title'])?></h1><span class="status"><?=status_label(effective_status($item))?></span><div class="detail-price"><?=money($item['price'])?></div><p class="detail-description"><?=e($item['description'])?></p><dl><dt>Muallif</dt><dd><?=e($item['owner_name'])?></dd><dt>Telefon</dt><dd><?=e($item['phone'])?></dd><dt>Amal qilish muddati</dt><dd><?=e($item['expires_at'])?></dd></dl><?php if($user&&($user['role']==='admin'||$user['id']==$item['user_id'])):?><div class="actions"><?php if(!in_array($item['status'],['blocked','archived'],true)):?><a class="secondary" href="<?=url('listing-form',['id'=>$item['id']])?>">Tahrirlash</a><form method="post" action="<?=url('listing-extend')?>"><?=csrf()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="expected_expires_at" value="<?=e($item['expires_at'])?>"><button class="primary">30 kunga uzaytirish</button></form><form method="post" action="<?=url('listing-expire')?>"><?=csrf()?><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="expected_expires_at" value="<?=e($item['expires_at'])?>"><button class="secondary">Muddatni tugatish</button></form><?php endif?></div><?php if($item['status']!=='archived'):?><form method="post" action="<?=url('listing-delete')?>" class="danger-zone" data-confirm="E’lonni arxivlashni tasdiqlaysizmi?"><?=csrf()?><input type="hidden" name="id" value="<?=$item['id']?>"><label class="checkbox"><input type="checkbox" name="confirm" value="yes" required>Arxivlashni tasdiqlayman. Tarix saqlanadi.</label><button class="danger">E’lonni arxivlash</button></form><?php endif;endif?></article><aside class="panel"><h2>Ishonchli hamjamiyat</h2><p class="muted">E’lon tafsilotlarini tekshiring. Noto‘g‘ri ma’lumot ko‘rsangiz, moderatorga xabar bering.</p><?php if($user&&$user['id']!=$item['user_id']&&effective_status($item)==='active'):?><form class="app-form" method="post" action="<?=url('complaint-create')?>" data-validate><?=csrf()?><input type="hidden" name="listing_id" value="<?=$item['id']?>"><label>Shikoyat sababi<textarea name="reason" required minlength="15" maxlength="2000" rows="4"></textarea></label><button class="secondary">Shikoyat yuborish</button></form><?php elseif(!$user):?><a class="secondary" href="<?=url('login')?>">Shikoyat uchun tizimga kiring</a><?php endif?></aside></div>
<?php if($user&&($user['role']!=='user'||$user['id']==$item['user_id'])):?><section class="panel attachments"><h2>Himoyalangan biriktirmalar</h2><p class="muted">Fayllar faqat e’lon egasi, administrator va moderatorga ochiladi.</p><?php foreach($attachments as $a):?><div class="attachment"><div><a href="<?=url('file-download',['id'=>$a['id']])?>"><?=e($a['original_name'])?></a><p class="muted"><?=e($a['description'])?> · <?=e($a['mime'])?> · <?=round($a['size']/1024)?> KB</p></div><?php if($user['role']==='admin'||$user['id']==$item['user_id']):?><form method="post" action="<?=url('file-delete')?>" data-confirm="Faylni o‘chirishni tasdiqlaysizmi?"><?=csrf()?><input type="hidden" name="id" value="<?=$a['id']?>"><label class="checkbox"><input required name="confirm" type="checkbox" value="yes">Tasdiqlayman</label><button class="danger">O‘chirish</button></form><?php endif?></div><?php endforeach?><?php if(!$attachments):?><p>Hali fayl biriktirilmagan.</p><?php endif?><?php if($user['role']==='admin'||$user['id']==$item['user_id']):?><form class="app-form upload-form" action="<?=url('file-upload')?>" method="post" enctype="multipart/form-data" data-validate><?=csrf()?><input type="hidden" name="listing_id" value="<?=$item['id']?>"><label>Faylni biriktirish yoki almashtirish<select name="replace_id"><option value="">Yangi fayl qo‘shish</option><?php foreach($attachments as $a):?><option value="<?=$a['id']?>"><?=e($a['original_name'])?> ni almashtirish</option><?php endforeach?></select></label><label>Tavsif<input name="description" required minlength="2" maxlength="500"></label><label>Fayl (rasm 2 MB, PDF 5 MB, MP4 20 MB)<input type="file" name="file" required accept=".jpg,.jpeg,.png,.webp,.pdf,.mp4" data-upload></label><p class="muted" data-file-hint aria-live="polite"></p><button class="primary">Faylni yuklash</button></form><?php endif?></section><?php endif?></section>
